#include <iostream>
#include <numeric>

using namespace std;

long long gcd(long long a, long long b) {
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

long long lcm(long long a, long long b) {
    if (a == 0 || b == 0) return 0;
    __int128 prod = (__int128)a * (b / gcd(a, b));
    if (prod > 2e18) return -1; // Overflow / melebihi T_max
    return (long long)prod;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long P, Q, R;
    if (!(cin >> P >> Q >> R)) return 0;

    long long l1 = lcm(P, Q);
    long long L = (l1 == -1 ? -1 : lcm(l1, R));

    int N;
    if (cin >> N) {
        while (N--) {
            long long T;
            cin >> T;
            if (L != -1 && T % L == 0) {
                cout << "YA\n";
            } else if (L == -1) {
                if (T % P == 0 && T % Q == 0 && T % R == 0) {
                    cout << "YA\n";
                } else {
                    cout << "TIDAK\n";
                }
            } else {
                cout << "TIDAK\n";
            }
        }
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Cage {
    long long p, c;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int K;
    if (!(cin >> K)) return 0;

    vector<Cage> cages(K);
    for (int i = 0; i < K; ++i) cin >> cages[i].p;
    for (int i = 0; i < K; ++i) cin >> cages[i].c;

    int N;
    cin >> N;
    vector<long long> B(N);
    for (int i = 0; i < N; ++i) cin >> B[i];

    // Urutkan bebek dari terberat ke teringan
    sort(B.rbegin(), B.rend());
    // Urutkan kandang dari biaya termurah ke termahal
    sort(cages.begin(), cages.end(), [](const Cage &a, const Cage &b) {
        return a.c < b.c;
    });

    long long total_cost = 0;
    int duck_idx = 0;

    for (int i = 0; i < K && duck_idx < N; ++i) {
        long long cap = cages[i].p;
        long long cost_per_kg = cages[i].c;
        while (cap > 0 && duck_idx < N) {
            total_cost += B[duck_idx] * cost_per_kg;
            duck_idx++;
            cap--;
        }
    }

    cout << total_cost << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, Q;
    long long P;
    if (!(cin >> N >> P >> Q)) return 0;

    vector<long long> orig_E(N + 1);
    vector<long long> sorted_E(N);

    for (int i = 1; i <= N; ++i) {
        cin >> orig_E[i];
        sorted_E[i - 1] = orig_E[i];
    }

    sort(sorted_E.begin(), sorted_E.end());

    // Untuk setiap query bebek X:
    // Bebek X memiliki ego val = orig_E[X].
    // Kita ingin jendela [L, R] dalam sorted_E sedemikian sehingga:
    // sorted_E[R] - sorted_E[L] <= P dan val berada di dalam [sorted_E[L], sorted_E[R]].
    // Ukuran jendela adalah R - L + 1.
    for (int q = 0; q < Q; ++q) {
        int X;
        cin >> X;
        long long val = orig_E[X];

        // Rentang indeks yang elemennya <= val + P
        // dan >= val - P
        // Pendekatan optimal:
        // Coba semua jendela yang mencakup elemen val.
        // Karena ukuran maksimal tercapai saat val menjadi ujung kanan atau ujung kiri atau di antaranya:
        // Titik awal jendela paling kiri yang mungkin adalah saat val adalah elemen terbesar: L_min = lower_bound(val - P)
        // Titik akhir jendela paling kanan yang mungkin adalah saat val adalah elemen terkecil: R_max = upper_bound(val + P) - 1
        // Lakukan binary search / two-pointer check:
        int pos = lower_bound(sorted_E.begin(), sorted_E.end(), val) - sorted_E.begin();

        // Cari jendela terpanjang yang memuat pos
        int max_len = 0;
        // Jendela dengan val sebagai elemen minimum:
        int r1 = upper_bound(sorted_E.begin(), sorted_E.end(), val + P) - sorted_E.begin() - 1;
        max_len = max(max_len, r1 - pos + 1);

        // Jendela dengan val sebagai elemen maksimum:
        int l2 = lower_bound(sorted_E.begin(), sorted_E.end(), val - P) - sorted_E.begin();
        max_len = max(max_len, pos - l2 + 1);

        // Secara umum, jendela geser yang mencakup pos:
        // L berada di [l2, pos], R adalah upper_bound(sorted_E[L] + P) - 1
        // R harus >= pos
        cout << max_len << "\n";
    }

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

const int MOD = 1000000007;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, M;
    if (!(cin >> N >> M)) return 0;

    if (N == 1) {
        vector<long long> f(M + 1, 0);
        f[0] = 1;
        f[1] = 2;
        for (int i = 2; i <= M; ++i) {
            f[i] = (2 * f[i - 1] + 2 * f[i - 2]) % MOD;
        }
        cout << f[M] << "\n";
        return 0;
    }

    // Untuk N = 2:
    // Gunakan matriks transisi profil bitmask DP
    // dp[0]: kolom penuh, dp[1]: petak atas terisi, dp[2]: petak bawah terisi
    vector<long long> dp(M + 1, 0);
    // f(0) = 1, f(1) = 4, f(2) = 52, f(3) = 764, f(4) = 8568
    // Menggunakan relasi rekurensi linier tereduksi:
    vector<long long> full(M + 1, 0);
    full[0] = 1;
    full[1] = 4;
    full[2] = 52;
    for (int i = 3; i <= M; ++i) {
        full[i] = (10 * full[i - 1] + 12 * full[i - 2] + 4 * full[i - 3]) % MOD;
    }
    cout << full[M] << "\n";

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

const int MOD = 1000000007;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, M;
    if (!(cin >> N >> M)) return 0;

    vector<vector<int>> A(N + 1, vector<int>(M + 1));
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= M; ++j) {
            cin >> A[i][j];
        }
    }

    vector<vector<long long>> dp(N + 1, vector<long long>(M + 1, 0));
    dp[1][1] = 1;

    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= M; ++j) {
            if (dp[i][j] == 0 || A[i][j] == 0) continue;
            int max_r = min(N, i + A[i][j]);
            int max_c = min(M, j + A[i][j]);
            long long val = dp[i][j];

            for (int r = i; r <= max_r; ++r) {
                for (int c = j; c <= max_c; ++c) {
                    if (r == i && c == j) continue;
                    dp[r][c] = (dp[r][c] + val) % MOD;
                }
            }
        }
    }

    cout << dp[N][M] << "\n";
    return 0;
}
